import java.util.*;

class Solution {
    static int shortestOverQuota(int[] usage, int quota) {
        int best = 0, total = 0, start = 0;
        for (int end = 0; end < usage.length; end++) {
            total += usage[end];
            while (total >= quota) {
                int length = end - start + 1;
                if (best == 0 || length < best) best = length;
                total -= usage[start++];
            }
        }
        return best;
    }
}
